import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Retro — catopt-onnx: 75% → 100% coverage in one climb","description":"","frontmatter":{},"headers":[],"relativePath":"graphopt/project/retros/onnx-package.md","filePath":"vendored/graphopt/project/retros/onnx-package.md"}`),a={name:`graphopt/project/retros/onnx-package.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="retro-—-catopt-onnx-75-→-100-coverage-in-one-climb" tabindex="-1">Retro — catopt-onnx: 75% → 100% coverage in one climb <a class="header-anchor" href="#retro-—-catopt-onnx-75-→-100-coverage-in-one-climb" aria-label="Permalink to “Retro — catopt-onnx: 75% → 100% coverage in one climb”">​</a></h1><h2 id="the-arc" tabindex="-1">The arc <a class="header-anchor" href="#the-arc" aria-label="Permalink to “The arc”">​</a></h2><p><code>catopt-onnx</code> landed as a deliberately-unfloored package (the sink in <code>f3b43f1</code>, the source in <code>32fed70</code>) — measured honest gap at climb start: <strong>75%</strong> statement+branch coverage, with <code>liftmap.py</code> (the ONNX→IR op table) at 40% and <code>lift.py</code> at 79%. The climb ran in two files mirroring the modules they cover:</p><table tabindex="0"><thead><tr><th>file</th><th>scope</th><th>result</th></tr></thead><tbody><tr><td><code>tests/test_onnx_liftmap.py</code> (~110 tests)</td><td><code>liftmap</code> per-op minted spellings, attr folds, composed lifts and every declared refusal; <code>lift.py</code> engine edges</td><td>liftmap 40→100, lift 79→100</td></tr><tr><td><code>tests/test_onnx_opmap.py</code> (~40 tests)</td><td><code>opmap</code> alternative attr spellings and refusals; <code>lower</code>/<code>arrays</code>/<code>report</code> edges</td><td>all four → 100</td></tr></tbody></table><p>Helpers reuse <code>tests.test_onnx_source</code>&#39;s model builders; the new seam is <code>_lifter(...)</code> driving <code>GraphLifter</code> directly with a partial <code>value_info</code> table — the same object <code>_collect_value_info</code> produces when ONNX&#39;s own inference leaves an intermediate unshaped (an honest input of the class, not a fake). Final measured number: <strong>100% — 1673 statements, 514 branches, zero misses, zero suppressions.</strong> The package joins the <code>fail_under=100</code> wall (not a separate ratchet — the measured number IS the wall).</p><h2 id="what-the-climb-proved-beyond-lines" tabindex="-1">What the climb proved (beyond lines) <a class="header-anchor" href="#what-the-climb-proved-beyond-lines" aria-label="Permalink to “What the climb proved (beyond lines)”">​</a></h2><p>Three real defects surfaced — two fixed in the same change, one documented as an upstream deviation:</p><ol><li><strong>Non-default-domain nodes were not refused.</strong> Both docstrings (<code>liftmap.ONNX_LIFTS</code>, <code>lift_model</code>) claimed a node with a non-empty <code>domain</code> &quot;refuses through the missing-entry path&quot; — but <code>_lift_node</code> never checked <code>node.domain</code>, so an <code>ai.onnx.ml</code>-domain <code>Relu</code> silently lifted as default-domain <code>relu</code> (a vendor <code>Add</code> could be <em>anything</em>). Fixed with a domain guard in <code>_lift_node</code>, mirrored in <code>_scan_constants</code> so a foreign <code>Constant</code> can&#39;t slip a leaf into the environment. Pinned by <code>test_a_non_default_domain_node_is_refused</code>.</li><li><strong><code>_emit_args</code> typed scalar constants by the <em>first</em> sibling.</strong><code>where(gt(x,a), x, 0.0)</code> — exactly what the <code>ThresholdedRelu</code> lifter mints — picked the bool predicate&#39;s dtype for the <code>0.0</code> constant and emitted an invalid <code>Where(bool→float mix)</code> graph. Now a scalar adopts the first <em>non-boolean</em> sibling dtype (a predicate is never the constant&#39;s own type), falling back to the first tracked dtype for all-bool terms. Pinned by the thresholded-relu round trip.</li><li><strong><code>remainder</code> lowered to an unrunnable graph for int dtypes.</strong><code>Mod(fmod=0)</code> on <code>int64</code> inputs mints <code>remainder</code>, which the sink composed as <code>x - floor(x/y)*y</code> — but ORT has no integer <code>Floor</code> kernel either. <code>Mod(fmod=0)</code> IS the integer path the runtime requires, so <code>_remainder</code> now emits it for <code>i</code>/<code>u</code>-kind dtypes and keeps the composition for floats. Pinned by the <code>mod-int</code> round trip.</li></ol><p><strong>Upstream finding (not a bug, a deviation):</strong> ONNX&#39;s spec and its reference evaluator say <code>Gather</code> with a scalar index drops the axis (<code>(4,)</code>); onnxruntime&#39;s CPU EP keeps a <code>(1, 4)</code>. The lifter is spec-faithful — <code>test_gather_scalar_index_paths</code> verifies the lifted program against NumPy <code>w[2]</code> rather than ORT&#39;s deviation.</p><h2 id="reachable-by-construction-arcs-the-climb-exposed" tabindex="-1">Reachable-by-construction arcs the climb exposed <a class="header-anchor" href="#reachable-by-construction-arcs-the-climb-exposed" aria-label="Permalink to “Reachable-by-construction arcs the climb exposed”">​</a></h2><p>Two branches looked dead and weren&#39;t — the honest reads:</p><ul><li><code>lift.py</code> <code>_const_leaf</code>&#39;s param cache (<code>params.get</code> hit): the <code>_env</code> memo means <code>term()</code> calls it once per name, but the graph-<em>output</em> path resolves leaves without the memo — a model listing the same constant name as two outputs re-enters the materialiser. <code>test_a_twice_named_constant_output_materialises_once</code> covers it.</li><li><code>lift.py</code> <code>_lift_node</code>&#39;s <code>if name:</code> filter on bound dicts: no shipped lifter produces an empty-name key, but the guard is the table&#39;s contract for <em>registered</em> lifters — exercised by registering a lifter that binds <code>&quot;&quot;</code> (<code>monkeypatch.setitem</code> on <code>ONNX_LIFTS</code>, the documented extension seam) and asserting the env stays clean.</li></ul><p>Nothing needed a <code>pragma: no cover</code> — the wall is honest.</p><h2 id="honest-seams-documented-not-fakes" tabindex="-1">Honest seams (documented, not fakes) <a class="header-anchor" href="#honest-seams-documented-not-fakes" aria-label="Permalink to “Honest seams (documented, not fakes)”">​</a></h2><ul><li><code>GraphLifter(graph, initializers=..., value_info={})</code> — drives the &quot;not statically known&quot; refusals (squeeze/unsqueeze/split/ gather/conv/layer-norm/global-pool/CastLike) through the same partial table <code>_collect_value_info</code> produces when inference can&#39;t type an intermediate.</li><li><code>_raw_model(...)</code> — builds the same <code>ModelProto</code> minus <code>onnx.checker</code>, for deliberately ill-formed-but-constructible graphs (extra outputs, empty output names, duplicate output names) that an exporter could still emit and the lifter must still answer.</li></ul><h2 id="floor-statement" tabindex="-1">Floor statement <a class="header-anchor" href="#floor-statement" aria-label="Permalink to “Floor statement”">​</a></h2><p><code>catopt_onnx</code> reports in the main <code>coverage report</code> wall (<code>fail_under=100</code>, <code>--omit=&quot;*/catopt_discovery/*&quot;</code>); discovery keeps its own <code>--fail-under=99</code> ratchet. The ONNX tests importorskip <code>onnx</code>/<code>onnxruntime</code> — the package declares both as dependencies, so the floor assumes the declared environment (same convention as the CUDA-marked tests).</p>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};